from common import *
from preflight import main as preflight

def ts(seconds):
 ms=round(seconds*1000);return f'{ms//60000:02}:{ms//1000%60:02}.{ms%1000:03}'
def main():
 m=load_manifest();p=preflight();a=json.loads((WORK/'audio-timeline.json').read_text());c=p['chorusRepeat'];o=p['outroMusic'];m3=p['musicCorrection'];ending=p['directEnding']
 lines=['# OPPO Bắc Ninh – Gửi một nửa yêu thương | Final Polished','',f"Timeline mới: **{ts(m['totalFrames']/60)}**, **{m['totalFrames']} frame**, 75 cảnh. Đầu ra H.264 CRF 17, 2560×1440, 60 FPS; AAC stereo 48 kHz 320 kb/s.",'','Bản này tiếp tục dự án đã duyệt dài 09:26.333. Toàn bộ 52 ảnh, thứ tự nhân sự, thời lượng ảnh 6 giây, hiệu ứng và 16 đoạn cắt lời nói/tốc độ đã duyệt được giữ nguyên. Mốc cũ trước phần closing vẫn là mốc mới; chỉ Outro dời sớm 17 giây.','','## 1. Bảng tên 16 nhân sự','','Giữ bố cục, nền xanh OPPO đậm bán trong suốt, tên trắng và chức vụ champagne. Hiệu ứng đi từ dưới lên/fade và cửa sổ hiện 3,75 giây giữ nguyên; bảng tên nằm ngoài vùng video người nói. Chức vụ người số 1 đã được người dùng xác nhận là **GIÁM ĐỐC KINH DOANH**.','','| # | Tên hiển thị | Chức vụ | Bắt đầu scene | Thời lượng scene |','|---|---|---|---|---|']
 for s in m['scenes']:
  if s['kind']=='wish':lines.append(f"| {s['number']} | {s['displayName']} | {s['displayRole']} | {ts(s['startFrame']/60)} | {s['durationInFrames']/60:.2f}s |")
 lines+=['','Mỗi scene lời chúc vẫn dưới 18 giây. Tên/chức vụ nguồn trong tên file vẫn được lưu riêng; chỉ thông tin hiển thị có tiền tố và chức vụ số 1 được cập nhật.','','## 2. Sửa vùng nhạc 05:28–05:35','',f"Bài hát trước đây kết thúc tại **{ts(m3['oldSongEndSeconds'])}**, khi ảnh còn hiển thị. Đã mở rộng đoạn nguồn từ 138,72–202,90s thành **138,72–211,18s**, đến hết câu/đoạn hát tiếp theo. Crossfade **{m3['newCrossfadeStartSeconds']:.3f}–{m3['newSongEndSeconds']:.3f}s** ({ts(m3['newCrossfadeStartSeconds'])}–{ts(m3['newSongEndSeconds'])}), dài 0,55 giây.",f"Ảnh cuối của nhóm kết thúc tại **{ts(m3['lastPhotoEndSeconds'])}**; lời nói nam đầu tiên bắt đầu tại **{ts(m3['nextVoiceStartSeconds'])}**. Nhạc hát vì thế đi hết phần ảnh; instrumental tiếp nhận tại bảng dẫn trước người nói, rồi tự hạ dưới giọng nói. Hai nhóm nhạc đầu giữ nguyên.",'','## 3. Điệp khúc cao trào','',f"Đoạn nguồn **{c['sourceStartSeconds']:.2f}–{c['sourceEndSeconds']:.2f}s** của `public/music/NHẠC 20.10.mp3`, dài **{c['durationSeconds']:.2f}s**, phát tại **{ts(c['startSeconds'])}–{ts(c['endSeconds'])}** trong timeline mới. Giữ trọn các câu hát đến hết điệp khúc, không đổi tốc độ.",'','Đã so sánh ba đoạn điệp khúc tương ứng: RMS 0,17610 / 0,17550 / **0,18582**. Chọn lần cuối có năng lượng đều cao hơn và còn đủ headroom. Fade-in/out 0,8 giây. Đoạn lặp đi vào phần đuôi gần im của bài gốc, tránh hai câu hát chồng nhau. Fade-out bắt đầu tại **07:53.780**, sát bảng dẫn nhóm 4 (**07:53.783**); câu hát kết thúc **07:54.580**, trước lời nói video 13 tại **07:56.283**. Không đổi, lặp hoặc đảo ảnh.','','## 4. Xóa toàn bộ bốn closing','', '**Đã bỏ hoàn toàn `closing-0`, `closing-1`, `closing-2`, `closing-3` khỏi timeline và bước tạo đồ họa. Không chuyển bốn đoạn chữ sang nơi khác và không thêm cảnh thay thế.**','', 'Cụm closing của bản cũ đóng góp **17,000 giây** sau khi tính các overlap; xóa theo cấu trúc scene đúng yêu cầu mới nhất, thay vì chỉ cắt máy móc 14 giây ở giữa cụm.',f"Lời chúc của **Anh. PHẠM VĂN TÙNG** bắt đầu tại **{ts(ending['lastWishStartSeconds'])}** và giữ nguyên toàn bộ đoạn nói đã duyệt. Giọng nói kết thúc tại **{ts(ending['lastVoiceEndSeconds'])}**. Chuyển thẳng sang **Outro gốc** tại **{ts(ending['outroStartSeconds'])}**, crossfade hình **0,45 giây**; không có scene trung gian. Outro kết thúc tại **{ts(m['totalFrames']/60)}**.",'','Chữ và hiệu ứng vốn có bên trong file video Outro gốc được giữ nguyên theo yêu cầu, không thêm lớp lời chúc mới.','','## 5. Nhạc Outro riêng','', '**Đã tìm thấy đúng `public/music/Nhac outro.mp3`** (33,456 giây theo container; khoảng 33,362 giây giải mã). Video `Outro_20-10_OPPO_Bac_Ninh.mp4` dài đúng **20 giây**, không có stream âm thanh gốc; video được xuất ở tốc độ 1,00×, không cắt và không đổi thiết kế.',f"Chọn nguồn nhạc **{o['sourceStartSeconds']:.2f}–{o['sourceEndSeconds']:.2f}s**: giữ trọn câu hát cuối về OPPO Bắc Ninh, nhạc cao trào và nhịp kết có đuôi vang tự nhiên. Nhạc có tiền âm **0,20 giây** từ **{ts(o['startSeconds'])}**; ở frame đầu Outro, nguồn nhạc đang ở **11,60s**. Fade-in 0,25 giây, fade-out cuối 0,30 giây, không time-stretch.",'','Điểm nhấn nguồn 14,132s → video Outro 02,532s (tên OPPO Bắc Ninh đang đi vào khung); 16,002s → 04,402s (tiêu đề đang xuất hiện); nhịp kết 29,372s → 17,772s, tiếp theo là đuôi vang tới khi video kết thúc. Giữ nguyên ánh sáng/bokeh sang trọng đã có trong video gốc.',f"Nhạc instrumental của phần nam fade 0,45 giây trước Outro và bằng **0** từ **{ts(ending['instrumentalZeroFromSeconds'])}** trở đi. Phần tiền âm Outro không có lời hát đè lên câu chúc cuối.",'','## Preview và kiểm tra','', '- `01-labels.mp4`: bảng tên đầu tiên với chức vụ đã xác nhận; `labels-contact.jpg`: đủ 16 bảng tên.','- `02-music-transition.mp4`: 05:25–05:42.','- `03-chorus-reprise.mp4`: 07:29–07:58.','- `04-direct-outro.mp4`: video 16 và toàn bộ Outro gốc trong timeline mới.','', 'Preview kiểm tra số frame, H.264 60 FPS, AAC stereo, đối chiếu âm thanh với bản phối và giải mã toàn bộ. Chỉ sau khi preview/preflight đạt mới render toàn bộ. Kiểm tra cuối đối chiếu khung của cả 75 scene, 16 giọng nói, số frame, true peak, hình đen, khoảng mất tiếng và giải mã toàn bộ MP4. Báo cáo thực tế nằm trong artifact, không coi báo cáo preflight là bằng chứng render thành công.','','## Render và lấy file','','```bash','npm ci','python3 -m pip install -r scripts/final/requirements.txt','npm run render:fast','npm run verify:render','```','','Cần Linux/WSL2 với Node.js 22+, Python 3.12+, FFmpeg và `fonts-dejavu-core`. Để xem Studio: `npm run media:prepare`, `npm run media:stage`, `npm run studio`. Composition `OppoBacNinh2010` tự lấy timeline mới từ manifest và dùng cùng scene/bản phối như đường xuất nhanh.','','MP4: `out/oppo-bac-ninh-20-10-final-polished-1440p60.mp4`. GitHub Actions: **Render OPPO Final Polished 1440p60**. Artifact: **OPPO-Bac-Ninh-20-10-Final-Polished-1440p60**, lưu ít nhất 14 ngày. Bên trong có MP4, bốn preview, contact sheet bảng tên và hình ảnh, timeline, báo cáo preflight, preview, âm thanh và QA.']
 (ROOT/'FINAL-POLISHED.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
